   169		\begin{equation}\label{eq:tildewj-product-form}
   170			\tilde{W}^j(\tilde{u})
   171			= \Big( \sum_{g_X,g_Z} (-1)^{\tr(e_j (\mathrm{Dec}(g_W) \cdot \tilde{u}))} \, \hat{S}_{g_X,g_Z} \Big) \ot \tau^W(e_j \tilde{u})\;,
